/* HTTP/1.1 helpers for the WebServer network. Lent to consumers as `libhttp`. */
#include <sys/types.h>
#include <sys/socket.h>
#include <sys/select.h> /* struct timeval for SO_RCVTIMEO */
#include <netinet/in.h>
#include <fcntl.h>
#include <poll.h>
#include <errno.h>

#define HTTP_MAX_HEADER 8192
#define HTTP_MAX_BODY 65536

/* Listening socket shared by the http_* functions; -1 when closed. */
static int http_listener = -1;

/* Heap copy of `length` bytes plus a terminating NUL, or NULL. */
static char *http_copy(const char *text, size_t length)
{
    char *copy = (char *)malloc(length + 1U);

    if (copy != NULL) {
        memcpy(copy, text, length);
        copy[length] = '\0';
    }
    return copy;
}

static int http_lower(int c)
{
    return (c >= 'A' && c <= 'Z') ? c - 'A' + 'a' : c;
}

/* Non-negative integer value of a header field (case-insensitive name), or -1. */
static long http_header_number(const char *header, const char *name)
{
    size_t length = strlen(name);
    const char *line = strstr(header, "\r\n");

    while (line != NULL && line[2] != '\0' && !(line[2] == '\r' && line[3] == '\n')) {
        const char *field = line + 2;
        size_t i = 0U;

        while (i < length && field[i] != '\0'
            && http_lower((unsigned char)field[i]) == http_lower((unsigned char)name[i])) {
            i++;
        }
        if (i == length && field[i] == ':') {
            char *end = NULL;
            long value = strtol(field + i + 1, &end, 10);
            return (end != field + i + 1 && value >= 0) ? value : -1;
        }
        line = strstr(field, "\r\n");
    }
    return -1;
}

const char *http_status_text(int status)
{
    switch (status) {
    case 200: return "OK";
    case 400: return "Bad Request";
    case 404: return "Not Found";
    case 405: return "Method Not Allowed";
    case 408: return "Request Timeout";
    case 413: return "Content Too Large";
    case 431: return "Request Header Fields Too Large";
    case 500: return "Internal Server Error";
    default: return "Unknown";
    }
}

/* Writes every byte, retrying on EINTR and never raising SIGPIPE; 0 on success. */
static int http_write_all(int connection, const char *data, size_t length)
{
    while (length > 0U) {
#ifdef MSG_NOSIGNAL
        ssize_t written = send(connection, data, length, MSG_NOSIGNAL);
#else
        ssize_t written = send(connection, data, length, 0);
#endif
        if (written < 0) {
            if (errno == EINTR) {
                continue;
            }
            return -1;
        }
        data += written;
        length -= (size_t)written;
    }
    return 0;
}

/* Answers a connection that never became a request, then closes it. */
static void http_reject(int connection, int status)
{
    char reply[256];
    const char *text = http_status_text(status);
    int length = snprintf(reply, sizeof(reply),
        "HTTP/1.1 %d %s\r\nContent-Type: text/plain; charset=utf-8\r\nContent-Length: %zu\r\n"
        "Connection: close\r\nServer: Wirecraft-WebServer/0.1\r\n\r\n%d %s\n",
        status, text, strlen(text) + 5U, status, text);

    if (length > 0) {
        (void)http_write_all(connection, reply, (size_t)length);
    }
    close(connection);
}

int http_listen(int port, int any_address)
{
    struct sockaddr_in address;
    int enable = 1;
    int flags;

    if (port <= 0 || port > 65535) {
        return -1;
    }
    http_listener = socket(AF_INET, SOCK_STREAM, 0);
    if (http_listener < 0) {
        return -1;
    }
    (void)setsockopt(http_listener, SOL_SOCKET, SO_REUSEADDR, &enable, sizeof(enable));
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_port = htons((uint16_t)port);
    address.sin_addr.s_addr = htonl(any_address ? INADDR_ANY : INADDR_LOOPBACK);
    flags = fcntl(http_listener, F_GETFL, 0);
    if (bind(http_listener, (struct sockaddr *)&address, sizeof(address)) != 0
        || listen(http_listener, 64) != 0 || flags < 0
        || fcntl(http_listener, F_SETFL, flags | O_NONBLOCK) != 0) {
        close(http_listener);
        http_listener = -1;
        return -1;
    }
    return 0;
}

int http_wait(int timeout_ms)
{
    struct pollfd watched;

    if (http_listener < 0) {
        return 0;
    }
    watched.fd = http_listener;
    watched.events = POLLIN;
    watched.revents = 0;
    return poll(&watched, 1, timeout_ms) > 0 && (watched.revents & POLLIN) != 0;
}

void http_close(void)
{
    if (http_listener >= 0) {
        close(http_listener);
        http_listener = -1;
    }
}

int http_accept(unsigned long sequence, ReqRep *out)
{
    static char buffer[HTTP_MAX_HEADER + HTTP_MAX_BODY + 1];
    struct timeval timeout = { 2, 0 };
    size_t received = 0U;
    size_t header_length;
    size_t total;
    char *end = NULL;
    char id[32];
    long body_length;
    int connection = accept(http_listener, NULL, NULL);

    if (connection < 0) {
        return (errno == EAGAIN || errno == EWOULDBLOCK || errno == EINTR) ? 0 : -1;
    }
    (void)setsockopt(connection, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout));
    while (end == NULL) {
        ssize_t count;

        if (received >= HTTP_MAX_HEADER) {
            http_reject(connection, 431);
            return 0;
        }
        count = recv(connection, buffer + received, HTTP_MAX_HEADER - received, 0);
        if (count < 0 && errno == EINTR) {
            continue;
        }
        if (count <= 0) {
            http_reject(connection, received == 0U && count < 0 ? 408 : 400);
            return 0;
        }
        received += (size_t)count;
        buffer[received] = '\0';
        end = strstr(buffer, "\r\n\r\n");
    }
    header_length = (size_t)(end - buffer) + 4U;
    body_length = http_header_number(buffer, "Content-Length");
    if (body_length < 0) {
        body_length = 0;
    }
    if (body_length > HTTP_MAX_BODY) {
        http_reject(connection, 413);
        return 0;
    }
    total = header_length + (size_t)body_length;
    while (received < total) {
        ssize_t count = recv(connection, buffer + received, total - received, 0);

        if (count < 0 && errno == EINTR) {
            continue;
        }
        if (count <= 0) {
            http_reject(connection, 400);
            return 0;
        }
        received += (size_t)count;
    }
    (void)snprintf(id, sizeof(id), "req-%lu", sequence);
    memset(out, 0, sizeof(*out));
    out->connection = connection;
    out->id = http_copy(id, strlen(id));
    out->request.header = http_copy(buffer, header_length);
    out->request.body = http_copy(buffer + header_length, (size_t)body_length);
    if (out->id == NULL || out->request.header == NULL || out->request.body == NULL) {
        free(out->id);
        free(out->request.header);
        free(out->request.body);
        http_reject(connection, 500);
        return 0;
    }
    return 1;
}

char *http_render_header(const Response *response)
{
    static const char format[] =
        "HTTP/1.1 %d %s\r\nContent-Type: %s\r\nContent-Length: %zu\r\nConnection: close\r\n"
        "Server: Wirecraft-WebServer/0.1\r\n%s\r\n";
    const char *type = response->content_type != NULL ? response->content_type : "text/plain; charset=utf-8";
    const char *allow = response->status == 405 ? "Allow: GET, HEAD\r\n" : "";
    size_t body = response->body != NULL ? strlen(response->body) : 0U;
    int length = snprintf(NULL, 0, format, response->status, http_status_text(response->status), type, body, allow);
    char *header;

    if (length < 0) {
        return NULL;
    }
    header = (char *)malloc((size_t)length + 1U);
    if (header != NULL) {
        (void)snprintf(header, (size_t)length + 1U, format, response->status,
            http_status_text(response->status), type, body, allow);
    }
    return header;
}

int http_resolve(ReqRep *pending, ReqRep *resolved)
{
    const char *header = resolved->response.header;
    const char *body = resolved->response.body;
    size_t body_length = body != NULL ? strlen(body) : 0U;
    int head = strncmp(pending->request.header, "HEAD ", 5) == 0;
    int status = 0;
    char method[8] = "";
    char path[128] = "";

    if (header == NULL || http_write_all(pending->connection, header, strlen(header)) != 0
        || (!head && body_length > 0U && http_write_all(pending->connection, body, body_length) != 0)) {
        status = -1;
    }
    (void)sscanf(pending->request.header, "%7s %127s", method, path);
    printf("%s %s %s %d %zu\n", pending->id, method, path, resolved->response.status, body_length);
    (void)fflush(stdout);
    close(pending->connection);
    free(pending->id);
    free(pending->request.header);
    free(pending->request.body);
    free(resolved->response.header);
    free(resolved->response.body);
    return status;
}
